{
  "cvars": {
    "ivs": [
      {
        "description": "Child's age (centered). Primary developmental predictor: we expect probability of choosing the majority option to change with age. This will be entered as a continuous predictor (age centered). Interaction with culture will test whether developmental trajectories differ across sites.",
        "columns": [
          "age_c"
        ]
      },
      {
        "description": "Cultural context / site ID. Categorical indicator for the population/site where the child was tested (Brazil, Canada, China, Japan, Namibia, Germany, Argentina, etc.). Treated as a categorical moderator of the age effect (included via an age * culture interaction in the model).",
        "columns": [
          "culture_cat"
        ]
      }
    ],
    "dv": {
      "description": "Binary indicator whether the child chose the majority-demonstrated option (1 = chose majority; 0 = chose minority or the unchosen option). This focuses the analysis on reliance on majority preference.",
      "columns": [
        "MajorityChoice"
      ]
    },
    "controls": [
      {
        "description": "Child's gender, coded as an indicator for being a boy (1 = boy, 0 = girl). Included as a control because gender can correlate with social learning strategies.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "is_boy"
        ]
      },
      {
        "description": "Whether the majority demonstration was shown first in the sequence (0/1). Included as a control because order effects could influence choice.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "majority_first"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy to avoid side-effects\n    df = df.copy()\n\n    # Drop rows missing any key variables required for the analysis\n    df = df.dropna(subset=['y', 'age', 'culture', 'gender', 'majority_first'])\n\n    # Dependent variable: binary indicator for choosing the majority option (y == 2)\n    df['MajorityChoice'] = (df['y'] == 2).astype(int)\n\n    # Center age to aid interpretation of main effects and interactions\n    df['age_c'] = df['age'].astype(float) - df['age'].astype(float).mean()\n\n    # Culture: make a categorical label used in modeling (string/category form)\n    # Keep the original numeric culture column if needed, but create culture_cat for use with C(...)\n    df['culture_cat'] = df['culture'].astype('category').astype(str)\n\n    # Gender: convert to binary indicator is_boy (1 = boy where original coding is 2 = boy)\n    df['is_boy'] = (df['gender'] == 2).astype(int)\n\n    # Ensure majority_first is integer 0/1\n    df['majority_first'] = df['majority_first'].astype(int)\n\n    # Return the transformed dataframe with all columns needed for modeling\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    import statsmodels.formula.api as smf\n\n    # Formula: main effect of centered age, main effect of culture (categorical), their interaction,\n    # plus controls for gender and demonstration order.\n    # Interaction age_c * C(culture_cat) allows the developmental slope to vary by culture.\n    formula = 'MajorityChoice ~ age_c * C(culture_cat) + is_boy + majority_first'\n\n    # Fit a logistic regression (binomial) model for the binary outcome MajorityChoice\n    # Using statsmodels' logit (maximum likelihood). Suppress fit output with disp=False.\n    model_fit = smf.logit(formula=formula, data=df).fit(disp=False)\n\n    # Return the fitted model object (contains parameter estimates, standard errors, etc.)\n    return model_fit\n"
}
